// Кейс: .qa/tests/expert/EXP-010.md · план: .qa/e2e-app/specs/app.md (1.45)
// ВНИМАНИЕ, @data: ЕДИНСТВЕННЫЙ тест этого экрана, который СОХРАНЯЕТ правила — создаёт новую версию в «גרסאות קודמות»
// с ТЕМИ ЖЕ числовыми значениями (меняется только пояснение). Сохранение применяется ко всем семьям с ближайшего мониторинга,
// но значения остаются прежними. Чисел и тега «זמני» тест не трогает. Версию удалить нельзя — каждый прогон добавляет запись.
// РУЧНОЕ ПРЕДУСЛОВИЕ: вход под jleprog34, запуск с BANCI_ACCOUNT=jleprog34 и BANCI_RULES_SAVE=1 (иначе — пропуск).
import { by, assert, skip } from '../../lib/appium.mjs';
import { requireExpert, openExpert, fieldBelow, hideKeyboard, assertTextRtl } from '../../lib/expert.mjs';

export const name = '«חוקי זיהוי»: сохранение с теми же значениями и пояснением «QA-AUTO RTL …» → «החוקים נשמרו», новая версия в «גרסאות קודמות» в RTL #7581cb @iphone @app @data';

const LABEL = 'מה נקבע ולמה';

export default async function (app) {
  requireExpert();
  if (process.env.BANCI_RULES_SAVE !== '1') {
    skip('тест сохраняет версию правил (те же значения, все семьи, запись в истории остаётся навсегда): запускать с BANCI_RULES_SAVE=1 только осознанно');
  }
  await openExpert(app);

  // 1. Только пояснение — с латиницы (QA-AUTO + дата). Числовые поля не трогаем.
  const stamp = new Date().toISOString().slice(0, 16).replace('T', ' ');
  const text = `QA-AUTO RTL ${stamp} בדיקה, ללא שינוי ערכים`;
  const field = await fieldBelow(app, LABEL);
  await field.click();
  await field.type(text);
  await hideKeyboard(app, LABEL);

  // 2. «שמירת החוקים» → «לשמור את החוקים?» → «שמירה לכולם» → «החוקים נשמרו».
  await (await app.scrollTo(by.exact('שמירת החוקים'), { what: 'кнопка «שמירת החוקים»' })).click();
  const dialogEl = by.contains('לשמור את החוקים?');
  const alert = await Promise.race([
    app.waitAlert({ timeout: 10000 }).catch(() => null),
    app.waitFor(dialogEl, { timeout: 10000, what: 'окно «לשמור את החוקים?»' }).catch(() => null),
  ]);
  assert(alert, 'окно «לשמור את החוקים?» появилось (без поля «מה נקבע ולמה» — «צריך לכתוב מה נקבע ולמה»)');
  if (alert.buttons) await app.exec('mobile: alert', { action: 'accept', buttonLabel: 'שמירה לכולם' });
  else await app.tap(by.exact('שמירה לכולם'), { what: 'кнопка «שמירה לכולם»' });
  await app.waitFor(by.contains('החוקים נשמרו'), { timeout: 20000, what: 'сообщение «החוקים נשמרו»' });

  // 3. Новая версия — первая в «גרסאות קודמות», пояснение в RTL.
  await app.restart();
  await openExpert(app);
  await app.scrollTo(by.exact('גרסאות קודמות'), { max: 20, what: 'раздел «גרסאות קודמות»' });
  const entry = await app.scrollTo(by.begins('QA-AUTO RTL'), { max: 12, what: 'новая версия с пояснением «QA-AUTO RTL …»' });
  await assertTextRtl(app, entry, 'пояснение новой версии «QA-AUTO RTL …»');
}
